arguments.command:
cd /workspace && cat > /tmp/dbg.c <<'EOF'
#include "epic_clean.h"
#include <stdio.h>
#include <string.h>
int main(void){
  char line[40000];
  size_t words=2;
  if(fscanf(stdin,"%zu",&words)==0) return 1;
  while(scanf("%39999s",line)==1){
    size_t n=strlen(line)/2;
    static uint8_t frame[9000];
    for(size_t i=0;i<n;i++){ unsigned v; char b[3]={0,0,0}; memcpy(b,line+2*i,2); sscanf(b,"%02x",&v); frame[i]=(uint8_t)v; }
    epic_wire_t w;
    bool ok=epic_wire_validate(frame,n,words,&w);
    uint8_t h[20]; memcpy(h,frame+14,20); h[10]=0; h[11]=0;
    uint16_t cke=epic_ipv4_checksum(h,20);
    uint32_t gotle=((uint32_t)frame[n-1]<<24)|((uint32_t)frame[n-2]<<16)|((uint32_t)frame[n-3]<<8)|frame[n-4];
    printf("len=%zu ok=%d psn=%u qpn=%x ack=%d plen=%zu\n", n, ok?1:0, w.psn, w.qpn, w.is_ack?1:0, w.payload_len);
    printf("  iplen_field=%d ethertype=%x ver_ihl=%02x proto=%d flags=%04x\n",
      (frame[16]<<8)|frame[17], (frame[12]<<8)|frame[13], frame[14], frame[23], (frame[20]<<8)|frame[21]);
    printf("  ipcksum field=%04x computed=%04x  udp_len=%d ports=%d,%d udpck=%d\n",
      (frame[24]<<8)|frame[25], cke, (frame[38]<<8)|frame[39], (frame[34]<<8)|frame[35], (frame[36]<<8)|frame[37], (frame[40]<<8)|frame[41]);
    printf("  opcode=%02x pad=%02x pkey=%04x qpn=%08x apsn=%08x\n", frame[42], frame[43], (frame[44]<<8)|frame[45],
      (frame[46]<<24)|(frame[47]<<16)|(frame[48]<<8)|frame[49], (frame[50]<<24)|(frame[51]<<16)|(frame[52]<<8)|frame[53]);
    printf("  icrc stored=%08x computed=%08x\n", gotle, epic_compute_icrc(frame,n));
  }
  return 0;
}
EOF
gcc -std=gnu11 -O1 -Iproject/include /tmp/dbg.c project/src/roce_packet.c project/src/sha256.c -o /tmp/dbg 2>&1 | head -20
tail -1 /tmp/dbg_frames.txt | cut -d' ' -f2 > /tmp/one.hex && echo "2 $(< /tmp/one.hex tr -d '\n')" | /tmp/dbg
